<?php
namespace App\Repositories; use App\Repositories\Contracts\CrudRepositoryInterface; use Illuminate\Database\Eloquent\Collection; use Illuminate\Database\Eloquent\Model;
abstract class EloquentRepository implements CrudRepositoryInterface {public function __construct(protected Model $model){}public function all(array $with=[]):Collection{return $this->model->newQuery()->with($with)->get();}public function find(int $id,array $with=[]):Model{return $this->model->newQuery()->with($with)->findOrFail($id);}public function create(array $data):Model{return $this->model->create($data);}public function update(Model $model,array $data):Model{$model->update($data);return $model->refresh();}public function delete(Model $model):void{$model->delete();}}
